var HZTowerServer={
  applying:false,
  apply:function(response){
    if(!response.hasData("tower_authoritative")||!ra.get_current())return;
    var state=response.getTypedObject("tower_authoritative"),raw=state.getTypedObject("tower").get_rawData(),game=ra.get_current(),tower=game.get_towers().getTower(raw.id);
    if(!tower)return;
    this.applying=true;
    try{
      tower.get_floorManagerPool().update(new d(raw.manager_pool));
      tower.get_elevator().get_managerPool().update(new d(raw.elevator.manager_pool));
      tower.get_vault().get_managerPool().update(new d(raw.vault.manager_pool));
      for(var j=0;j<raw.regions.length;j++){
        var definition=Lk.fromId(raw.regions[j].index),region=tower.getRegionByFloor(definition.get_fromIndex());
        if(region)region.update(new d(raw.regions[j]));
      }
      var pools=[tower.get_floorManagerPool(),tower.get_vault().get_managerPool(),tower.get_elevator().get_managerPool()];
      for(var k=0;k<pools.length;k++){
        var managers=pools[k].get_managers();
        for(var m=0;m<managers.length;m++){
          var manager=managers[m],assigned=null;
          if(k===0){for(var f=0;f<raw.floors.length;f++)if(raw.floors[f].manager_id===manager.get_id())assigned=tower.getFloor(raw.floors[f].index);}
          else {var target=k===1?tower.get_vault():tower.get_elevator();if((k===1?raw.vault:raw.elevator).manager_id===manager.get_id())assigned=target;}
          if(manager.get_assignedTarget()!==assigned)manager.set_assignedTarget(assigned);
        }
      }
      tower.get_elevator().update(new d(raw.elevator));tower.get_vault().update(new d(raw.vault));
      for(var i=0;i<raw.floors.length;i++)tower.getFloor(raw.floors[i].index).update(new d(raw.floors[i]));
      tower.set("objectives",raw.objectives);tower.set("max_floor_index",raw.max_floor_index);
      game.get_economy().get_area().get_bankAmount().set_value(state.getNumber("bank"));
      game.get_economy().get_boosts().set("active_boosts",state.getTypedObject("boosts").get_asArray());
      Sg.updateEconomyId();
    }finally{this.applying=false;}
  },
  send:function(args,ok,fail){
    args.tower_id=ra.get_current().get_towers().get_activeTowerId();
    Re.sendActionRequest("towerCommand",args,function(r){if(ok)ok();},fail);
  },
  kind:function(type){return type===1?"floor":type===2?"vault":"elevator";},
  managerArgs:function(op,manager,target){
    var kind=this.kind(manager.get_type());
    return {command:op,kind:kind,index:kind==="floor"&&target?target.get_index():0,manager_id:manager.get_id()};
  }
};
// O transporte local anima os indicadores; a entrega financeira é calculada no servidor.
var HZTowerOriginalAreaCredit=Rq.prototype.addBankAmount;
Rq.prototype.addBankAmount=function(amount,source,towerId){
  if(source==="vaultWorker")return;
  return HZTowerOriginalAreaCredit.call(this,amount,source,towerId);
};
var HZTowerOriginalRequest=Re.sendActionRequest;
Re.sendActionRequest=function(action,args,ok,fail,visible,background){
  return HZTowerOriginalRequest(action,args,function(result){
    // Os callbacks oficiais podem incrementar um piso ou somar renda; aplicar depois evita duplicação.
    if(action==="towerCommand"){HZTowerServer.apply(result.get_typedData());ok(result);}
    else {ok(result);
      if(action==="resetTowerEventProgress"){
        ra.reset();q.get_current().get_character()._towerEventData=new ra(result.get_typedData().getTypedObject("tower_event_data"));
        A.get_instance().showPanel("tower_event");
      }else HZTowerServer.apply(result.get_typedData());
    }
  },fail,visible,background);
};
gz.levelUpElevator=function(cost,target,count,ok,fail){HZTowerServer.send({command:"level",kind:"elevator",index:0,count:count},ok,fail);};
gz.levelUpVault=function(cost,target,count,ok,fail){HZTowerServer.send({command:"level",kind:"vault",index:0,count:count},ok,fail);};
gz.levelUpFloor=function(cost,target,count,ok,fail){HZTowerServer.send({command:"level",kind:"floor",index:target.get_index(),count:count},ok,fail);};
gz.unlockTowerFloor=function(cost,target,ok,fail){HZTowerServer.send({command:"unlock",kind:"floor",index:target.get_index()},ok,fail);};
gz.unlockTowerRegion=function(cost,target,ok,fail){HZTowerServer.send({command:"region",kind:"floor",index:target.get_index(),region:target.get_region().get_index()},ok,fail);};
gz.completeUnlockTowerRegion=function(target,ok,fail){HZTowerServer.send({command:"completeRegion",kind:"floor",index:target.get_index(),region:target.get_region().get_index()},ok,fail);};
Dw.hireManager=function(cost,pool,target,ok,fail){HZTowerServer.send({command:"hire",kind:HZTowerServer.kind(pool.get_type()),index:pool.get_type()===1?target.get_index():0},ok,fail);};
Dw.assignManager=function(manager,target,ok,fail){HZTowerServer.send(HZTowerServer.managerArgs("assign",manager,target),ok,fail);};
Dw.unassignManager=function(manager,target,ok,fail){HZTowerServer.send(HZTowerServer.managerArgs("unassign",manager,target),ok,fail);};
Dw.activateManager=function(manager,ok,fail){HZTowerServer.send(HZTowerServer.managerArgs("activate",manager,manager.get_assignedTarget()),ok,fail);};
Dw.sellManager=function(pool,manager,ok,fail){var args=HZTowerServer.managerArgs("sell",manager,null);if(args.kind==="floor")args.index=1;HZTowerServer.send(args,ok,fail);};
